        if (!$this->isAllowedConstraint($constraint)) {
            throw new UnexpectedException(sprintf('The constraint "%s" cannot be validated automatically because either it is a mapping between property/method names and constraints or it does not extend "%s". Use the "Valid" constraint to enable this.', ...));
