        }

        if ($value instanceof \Traversable || $value instanceof \ArrayObject) {
            $value = $value instanceof \ArrayObject ? $value->getArrayCopy() : iterator_to_array($value, false);
        }

        $this->validateConstraint($validator, $value, $constraint, ...);
    }
}
